customCSS:
/* Qubit Command visual system - overlay theme (no vendored file is edited).
   Loaded through the dashboard's own theming API: applyTheme() injects this
   string into a single <style id="qubit-theme-custom-css"> tag. Static
   import inspection reads it textually, never executing it. */
:root{
  --qubit-lime:#a3e635;--qubit-cyan:#22d3ee;--qubit-graphite:#10141c;
  --qubit-navy:#0b0e13;--qubit-panel:#161b24;
  --qubit-hairline:rgba(163,230,53,.16);
  --qubit-glow:0 0 0 1px rgba(163,230,53,.25),0 8px 32px rgba(0,0,0,.45);
  --qubit-ease:cubic-bezier(.23,1,.32,1);
}
.qubit-brandmark{font-weight:800;letter-spacing:.045em}
/* Hide the sidebar's built-in wordmark; the Qubit brand plugin renders the Qubit mark in that header slot. The mobile top bar keeps its own Qubit wordmark (no duplicate: the brand plugin slot only renders inside the sidebar header, not the lg:hidden top bar). */
div.flex.h-14.shrink-0 span.text-midground.font-bold{display:none!important}
::selection{background:rgba(163,230,53,.30);color:#fff}
html{scrollbar-color:rgba(163,230,53,.35) transparent}
*::-webkit-scrollbar{width:10px;height:10px}
*::-webkit-scrollbar-thumb{background:rgba(163,230,53,.28);border-radius:999px;border:2px solid transparent;background-clip:padding-box}
*::-webkit-scrollbar-thumb:hover{background:rgba(163,230,53,.45);background-clip:padding-box}
/* Accessibility: always-visible keyboard focus, no mouse-only surprise outlines. */
:where(a,button,[role="button"],input,select,textarea,summary,[tabindex]):focus-visible{outline:2px solid var(--qubit-lime);outline-offset:2px;border-radius:6px}
:where(a,button,[role="button"]):focus:not(:focus-visible){outline:none}
/* Motion: purposeful easing, and fully disabled for reduced-motion users. */
@media (prefers-reduced-motion:no-preference){
  a,button,[role="button"],.transition{transition-timing-function:var(--qubit-ease)}
  .qubit-live-dot{animation:qubit-pulse 1.6s ease-in-out infinite}
}
@keyframes qubit-pulse{0%,100%{opacity:.35}50%{opacity:1}}
@keyframes qubit-shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
@keyframes qubit-recover{0%{transform:translateY(2px);opacity:.4}100%{transform:none;opacity:1}}
/* Loading / streaming state. */
[aria-busy="true"],[data-state="loading"],.qubit-loading{position:relative}
[aria-busy="true"]::after,[data-state="loading"]::after,.qubit-loading::after{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(90deg,transparent,rgba(163,230,53,.10),transparent);background-size:200% 100%;animation:qubit-shimmer 1.4s linear infinite;pointer-events:none}
/* Empty state - dashed Qubit surface, never a dead blank box. */
[data-state="empty"],.qubit-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.5rem;min-height:8rem;color:var(--color-muted-foreground);border:1px dashed var(--qubit-hairline);border-radius:var(--radius);padding:1.25rem;text-align:center}
/* Degraded / unavailable - cyan informational rail. */
[data-state="degraded"],[data-state="unavailable"],.qubit-degraded{border-left:3px solid var(--qubit-cyan);background:rgba(34,211,238,.06);padding-left:.75rem}
/* Approval / pending confirmation - lime attention rail + glow. */
[data-state="pending"],[data-state="awaiting-approval"],.qubit-approval{border-left:3px solid var(--qubit-lime);background:rgba(163,230,53,.08);box-shadow:var(--qubit-glow)}
/* Cancellation / emergency stop - red rail. */
[data-state="cancelled"],[data-state="estop"],.qubit-cancelled{border-left:3px solid #e5484d;background:rgba(229,72,77,.08)}
/* Recovery / retry - amber rail with an entrance that respects motion settings. */
[data-state="recovering"],[data-state="retry"],.qubit-recovering{border-left:3px solid #f5a524;background:rgba(245,165,36,.08);animation:qubit-recover .3s var(--qubit-ease)}
/* Outcome chips. */
.qubit-success{color:#4ade80}.qubit-warning{color:#f5a524}.qubit-danger{color:#e5484d}
/* Responsive: keep desktop density, enlarge targets + text on narrow / touch. */
@media (max-width:768px){
  :root{--theme-base-size:15.5px}
  aside#app-sidebar{width:min(16rem,86vw)}
}
@media (pointer:coarse){
  button,[role="button"],a[href],input[type="checkbox"],input[type="radio"],select{min-height:44px;min-width:44px}
  nav a{padding-top:.5rem;padding-bottom:.5rem}
}
@media (prefers-contrast:more){
  :root{--qubit-hairline:rgba(163,230,53,.55);--color-border:rgba(232,240,228,.45)}
}
@media (forced-colors:active){
  :where(a,button,[role="button"]):focus-visible{outline:2px solid Highlight}
}
@media (min-width:1600px){main{max-width:none}}
